const summarizeAgentRunDeliveries = `-- name: SummarizeAgentRunDeliveries :one
SELECT count(*) FILTER (WHERE state IN ('pending','sending','reconciling'))::integer AS open,
  count(*) FILTER (WHERE state='failed')::integer AS failed,
  count(*) FILTER (WHERE state='outcome_unknown')::integer AS unknown,
  count(*) FILTER (WHERE state='cancelled')::integer AS cancelled,
  coalesce(min(outcome_message) FILTER (WHERE state IN ('failed','outcome_unknown')), '')::text AS message
 FROM agent_deliveries WHERE run_id=$1::text::uuid
`

type SummarizeAgentRunDeliveriesRow struct {
	Open      int32
	Failed    int32
	Unknown   int32
	Cancelled int32
	Message   string
}

func (q *Queries) SummarizeAgentRunDeliveries(ctx context.Context, db DBTX, runID string) (SummarizeAgentRunDeliveriesRow, error) {
	row := db.QueryRow(ctx, summarizeAgentRunDeliveries, runID)
	var i SummarizeAgentRunDeliveriesRow
	err := row.Scan(
		&i.Open,
		&i.Failed,
		&i.Unknown,
		&i.Cancelled,
		&i.Message,
	)
	return i, err
}

const supersedeAgentDeliveries = `-- name: SupersedeAgentDeliveries :many
UPDATE agent_deliveries d SET state='superseded', outcome_code='superseded',
  outcome_message='a later run''s delivery to the same destination replaced this one', finished_at=now(), updated_at=now()
 WHERE d.state IN ('pending','reconciling') AND EXISTS (SELECT 1 FROM agent_deliveries n
   WHERE n.idempotency_key=d.idempotency_key AND n.state IN ('pending','sending','reconciling','delivered')
   AND (n.created_at,n.id)>(d.created_at,d.id))
 RETURNING d.run_id::text AS run_id,d.destination,d.state
`

type SupersedeAgentDeliveriesRow struct {
	RunID       string
	Destination string
	State       string
}

// A waiting delivery gives way to a newer one for the same destination
// object that is still open or already delivered: the newer content wins.
func (q *Queries) SupersedeAgentDeliveries(ctx context.Context, db DBTX) ([]SupersedeAgentDeliveriesRow, error) {
	rows, err := db.Query(ctx, supersedeAgentDeliveries)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SupersedeAgentDeliveriesRow{}
	for rows.Next() {
		var i SupersedeAgentDeliveriesRow
		if err := rows.Scan(&i.RunID, &i.Destination, &i.State); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

